import{_ as l,l as r,o as e,c as n,v as t,p as s,x as i,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"熔石英与 CaF₂","description":"","frontmatter":{"title":"熔石英与 CaF₂","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/fused-silica-caf2.md","filePath":"litho/fused-silica-caf2.md","lastUpdated":1789023840000}'),p={name:"litho/fused-silica-caf2.md"};function m(_,a,f,u,E,C){const o=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="熔石英与-caf2" tabindex="-1">熔石英与 CaF₂ <a class="header-anchor" href="#熔石英与-caf2" aria-label="Permalink to &quot;熔石英与 CaF₂&quot;">​</a></h1><div class="epigraph"><p>193 nm 能用的大块光学材料就这几样：熔石英扛大部分，CaF₂ 补深紫外色散与透过。选错牌号，致密化和双折射一起来。</p><footer>—— 对照 193 nm 投影光学材料通识；[致密化](/litho/lens-compaction)、[双折射](/litho/birefringence-polarization)</footer></div><p><a href="/litho/lens-compaction">上一课</a>把熔石英损伤写成寿命。缺口是材料分工：哪些面必须 CaF₂、哪些熔石英就够。本课钉材料，不写镀膜配方。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>空气与水都不吸收 193 nm 到不能用，但玻璃会。普通光学玻璃在此是黑的。熔石英透过尚可、可做大口径，却有致密化与 \\(dn/dT\\)。CaF₂ 透过更好、色散不同，但硬脆、热导与应力双折射更麻烦，大口径贵。折反射设计是在这两种约束里分配厚度。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>末片与高通量面优先低吸收牌号；色差敏感组用 CaF₂。浸没接触面还要抗水与清洗。采购与再抛光周期进镜头寿命账，与气体罐分开。</p>',7)),(e(),s(h,null,{default:i(()=>[c(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20FS%5B%22%E7%86%94%E7%9F%B3%E8%8B%B1%22%5D%20--%3E%20BULK%5B%22%E5%A4%A7%E5%8F%A3%E5%BE%84%20%2F%20%E7%BB%93%E6%9E%84%22%5D%0A%20%20CAF%5B%22CaF2%22%5D%20--%3E%20UV%5B%22%E9%80%8F%E8%BF%87%20%2F%20%E8%89%B2%E6%95%A3%22%5D%0A%20%20BULK%20--%3E%20CAT%5B%22%E6%8A%98%E5%8F%8D%E5%B0%84%E7%BB%84%22%5D%0A%20%20UV%20--%3E%20CAT%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">157 nm 曾把 CaF₂ 推到极限后放弃量产。193 nm 浸没是材料还能撑住的最后一档 DUV 波长台阶。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>电子带隙决定本征吸收边；杂质和 OH 决定尾吸收，尾吸收决定热与致密化速率。CaF₂ 立方晶，应力下双折射，后课展开。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课如何量这台由两种材料拼起来的镜头的像差，而不是材料证书。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>193 nm 物镜是熔石英 + CaF₂ 的分配问题。</li><li>材料选择直接决定致密化与双折射预算。</li><li>出处：DUV 光学材料通识；致密化课。</li></ul>',7))])}const A=l(p,[["render",m]]);export{F as __pageData,A as default};
